/**
 * Product catalog service.
 *
 * This is the single source of truth for all product data.
 * To add, remove, or update products, edit the `catalog` array below.
 * The API handler and all frontend pages import from here.
 */

export type ProductCategory = 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export interface Product {
  id: string;
  name: string;
  category: ProductCategory;
  price: number;
  description: string;
  imageUrl: string;
}

