    category: 'textiles',
    price: 58,
    description: 'Handwoven from sustainably sourced natural fibers. Functional and beautifully crafted.',
    imageUrl: '/airo-assets/images/products/textiles-2',
  },
  {
    id: 't3',
    name: 'Macramé Wall Hanging',
    category: 'textiles',
    price: 85,
    description: 'A statement wall piece hand-knotted from organic cotton rope. Each one is unique.',
    imageUrl: '/airo-assets/images/products/textiles-3',
  },

  // ── Woodwork ─────────────────────────────────────────────────────────────
  {
    id: 'w1',
    name: 'Walnut Cutting Board',
    category: 'woodwork',
    price: 95,
    description: 'Hand-finished walnut cutting board with natural grain patterns. A kitchen heirloom.',
    imageUrl: '/airo-assets/images/products/woodwork-1',
  },
  {
    id: 'w2',
