    category: 'woodwork',
    price: 145,
    description: 'Minimalist wall shelf hand-crafted from solid oak. Clean lines, natural finish.',
    imageUrl: '/airo-assets/images/products/woodwork-3',
  },

  // ── Jewelry ───────────────────────────────────────────────────────────────
  {
    id: 'j1',
    name: 'Sterling Silver Ring',
    category: 'jewelry',
    price: 68,
    description: 'Hand-forged sterling silver ring with a hammered texture. Timeless and wearable.',
