    imageUrl: '/airo-assets/images/products/jewelry-3',
  },
];

/** Return all products, optionally filtered by category. */
export function getProducts(category?: ProductCategory | 'all'): Product[] {
  if (!category || category === 'all') return catalog;
  return catalog.filter((p) => p.category === category);
}

/** Return a single product by id, or undefined if not found. */
export function getProductById(id: string): Product | undefined {
  return catalog.find((p) => p.id === id);
}

/** Return the first `n` products (used for homepage featured section). */
export function getFeaturedProducts(n = 4): Product[] {
  return catalog.slice(0, n);
}

import type { Request, Response } from 'express';
import { getProducts, type ProductCategory } from '../../../lib/products.js';

export default function handler(req: Request, res: Response) {
  const { category } = req.query;

  const validCategories: ProductCategory[] = ['pottery', 'textiles', 'woodwork', 'jewelry'];
  const cat =
    category && typeof category === 'string' && validCategories.includes(category as ProductCategory)
      ? (category as ProductCategory)
      : 'all';

  res.json(getProducts(cat));
}

